import { Hono } from "hono";
import { customers } from "../data/customers";

export const customerRoutes = new Hono();

function parsePositiveInteger(value: string | undefined, fallback: number): number | undefined {
  if (value === undefined) return fallback;
  if (!/^\d+$/.test(value)) return undefined;

  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : undefined;
}

customerRoutes.get("/", (context) => {
  const pageQuery = context.req.query("page");
  const limitQuery = context.req.query("limit");

  // Preserve the raw Customer[] response for existing callers.
  if (pageQuery === undefined && limitQuery === undefined) {
    return context.json(customers);
  }

  // Pagination is opt-in through either parameter; omitted values use defaults.
  const page = parsePositiveInteger(pageQuery, 1);
  const limit = parsePositiveInteger(limitQuery, 10);
  if (page === undefined || limit === undefined) {
    return context.json(
      { error: "page and limit must be positive safe integers" },
      400,
    );
  }

  const total = customers.length;
  const start = (page - 1) * limit;
  return context.json({
    data: start >= total ? [] : customers.slice(start, start + limit),
    page,
    limit,
    total,
    totalPages: Math.ceil(total / limit),
  });
});

